Example usage: IncrementalTrainingConfigconfig;
config.training_data_collection="legal_training_samples";
config.base_model_path="models/llama-2-7b-chat.gguf";
config.adapter_version="";//Startfresh
config.rank=8;
config.num_epochs=3;

IncrementalLoRATrainertrainer(config,db);

//Initialtraining
autoresult=trainer.train(TrainingMode::INITIAL);
std::cout<<"Trainedadapter:"<<result.version<<"\n";

//Later:Incrementalupdatewithnewdata
config.adapter_version=result.version;
config.use_existing_adapter=true;
autoresult2=trainer.train(TrainingMode::INCREMENTAL);
std::cout<<"Updatedto:"<<result2.version<<"\n";
